import{PRESETS,calculate,validate}from'./pricing.mjs';
const $=s=>document.querySelector(s);const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={calc:'M5 3h14v18H5z M8 7h8 M8 11h1 M12 11h1 M16 11h1 M8 15h1 M12 15h1 M16 15h1 M8 18h1 M12 18h1 M16 18h1',home:'M3 10l9-7 9 7 M5 9v12h14V9 M9 21v-7h6v7',quotes:'M6 3h9l4 4v14H6z M14 3v5h5 M9 12h7 M9 16h5',book:'M3 4h7l2 2 2-2h7v16h-7l-2 1-2-1H3z M12 6v15',rocket:'M14 4c3-1 6-1 6-1s0 3-1 6l-6 6-5-5z M8 10H4l-2 5h6 M13 15v5l5-2v-5 M6 18l-3 3 M9 19l-3 3',arrow:'M4 12h16 M14 6l6 6-6 6',check:'M5 12l4 4L20 5',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v6l4 2',brief:'M3 7h18v14H3z M8 7V3h8v4 M3 12l9 3 9-3 M12 13v4',coins:'M12 3c-5 0-9 2-9 4s4 4 9 4 9-2 9-4-4-4-9-4 M3 7v5c0 2 4 4 9 4s9-2 9-4V7 M3 12v5c0 2 4 4 9 4s9-2 9-4v-5',sliders:'M5 3v18 M12 3v18 M19 3v18 M2 8h6 M9 16h6 M16 7h6',shield:'M12 3l8 3v6c0 5-8 9-8 9S4 17 4 12V6z M8 11l3 3 5-6',info:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 11v6 M12 7v1',spark:'M12 3l2 6 7 3-7 2-2 7-3-7-6-2 6-3z',lock:'M6 10h12v11H6z M8 10V6a4 4 0 0 1 8 0v4 M12 14v3',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',copy:'M8 8h13v13H8z M4 16H2V2h14v2',print:'M6 8V3h12v5 M6 18H3V9h18v9h-3 M6 14h12v7H6z',plus:'M12 4v16 M4 12h16',chevron:'M9 5l7 7-7 7',menu:'M3 6h18 M3 12h18 M3 18h18',trash:'M4 6h16 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7 M14 10v7',mail:'M3 5h18v14H3z M3 5l9 8 9-8',edit:'M14 4l6 6 M4 15L17 2l5 5L9 20l-6 1z',refresh:'M3 9a9 9 0 1 1 0 6 M3 3v6h6',leaf:'M20 3C10 2 3 5 4 13c1 8 16 11 16-10 M5 20L17 7',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6'};
const ic=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
const brand=()=>`<a href="#home" class="brand"><svg viewBox="0 0 34 36" fill="none" aria-hidden="true"><rect x="1" y="1" width="32" height="34" rx="9" fill="#155c45"/><path d="M11 27V9h9a6 6 0 0 1 0 12h-4" stroke="#dcedac" stroke-width="3.3" stroke-linecap="round"/><path d="M16 27v-6" stroke="#dcedac" stroke-width="3.3"/></svg><span>PriceMy<span class="service">Service</span></span></a>`;
let storageOK=true;function read(k,f){try{return JSON.parse(localStorage.getItem('pms-'+k))??f}catch{return f}}function put(k,v){try{localStorage.setItem('pms-'+k,JSON.stringify(v));return true}catch{storageOK=false;toast('Storage unavailable. Export your quote before leaving.');return false}}
let draft=read('draft',{...PRESETS.cleaning,preset:'cleaning'});if(Object.keys(validate(draft)).length)draft={...PRESETS.cleaning,preset:'cleaning'};
let profile=read('profile',{name:'',email:'',phone:'',address:'',currency:'USD',terms:'Work begins after written approval. Additional work requires a revised quote. Payment of the remaining balance is due on completion.'});let details=read('details',{client:'',email:'',address:'',scope:draft.scope,notes:'',validDays:14});let quotes=read('quotes',[]);if(!Array.isArray(quotes))quotes=[];let tasks=read('tasks',[]);let pilot=read('pilot',{business:'',email:'',service:'House cleaning',goal:''});let currentQuote=read('activeQuote',null),toastTimer;
const currency=()=>profile.currency||'USD';const money=(n,c=currency())=>new Intl.NumberFormat('en-US',{style:'currency',currency:c,maximumFractionDigits:2}).format(Number(n)||0);const whole=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:currency(),maximumFractionDigits:0}).format(n);const sym=()=>new Intl.NumberFormat('en-US',{style:'currency',currency:currency()}).formatToParts(0).find(x=>x.type==='currency').value;const num=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n);const date=(d=new Date())=>new Date(d).toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function download(name,text,type='text/plain'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied to clipboard.')}catch{download('pricemyservice-copy.txt',text);toast('Clipboard unavailable. Text downloaded instead.')}}
function go(route){if(location.hash==='#'+route)render();else location.hash=route;window.scrollTo(0,0)}
function foot(){return`<footer class="page-foot"><span>Thoughtful pricing. Stronger small businesses.</span><div><a href="#method">How the math works</a> &nbsp; · &nbsp; <a href="#privacy">Privacy & data</a></div></footer>`}
function heading(title,sub,action=''){return`<div class="page-heading"><div><h1>${title}</h1><p class="subtitle">${sub}</p></div>${action}</div>`}
function steps(n){return`<div class="steps" aria-label="Quote progress">${['Price your job','Build your quote','Ready to send'].map((s,i)=>`${i?'<span class="connector"></span>':''}<div class="step ${n===i+1?'current':n>i+1?'complete':''}"><b>${n>i+1?'✓':i+1}</b>${s}</div>`).join('')}</div>`}
const field=(key,label,opt={})=>{const value=opt.value??draft[key]??'';const adorn=opt.prefix?`<span class="adornment">${esc(sym())}</span>`:opt.suffix?`<span class="adornment">${esc(opt.suffix)}</span>`:'';return`<div class="field ${opt.full?'full':''}"><label for="${opt.ns||''}${key}">${label}</label><div class="input-wrap ${opt.prefix?'prefix':opt.suffix?'suffix':''}">${adorn}<input id="${opt.ns||''}${key}" ${opt.data||`data-price="${key}"`} name="${key}" type="${opt.type||'number'}" value="${esc(value)}" ${opt.type==='text'||opt.type==='email'?'':`min="${opt.min??0}" max="${opt.max??1000000}" step="${opt.step??'any'}" inputmode="decimal"`} ${opt.required?'required':''} ${opt.maxlength?`maxlength="${opt.maxlength}"`:''} aria-describedby="${opt.ns||''}${key}-help ${opt.ns||''}${key}-error"></div>${opt.help?`<p class="help" id="${opt.ns||''}${key}-help">${opt.help}</p>`:`<span id="${opt.ns||''}${key}-help"></span>`}<div class="error" id="${opt.ns||''}${key}-error"></div></div>`};
function section(icon,title,sub,count,content){return`<section class="card form-card"><div class="section-head"><div class="icon-box">${ic(icon)}</div><div><h2>${title}</h2><p>${sub}</p></div><span class="section-count">${count}</span></div>${content}</section>`}
function summary(mode='calc'){const r=calculate(draft),good=!Object.keys(r.errors).length;return`<div class="card summary"><div class="summary-top"><div class="top-label">Your recommended price <span class="live">LIVE ESTIMATE</span></div><div class="price">${good?whole(r.price):'—'}<small> / job</small></div><p>${good?'Before tax · based on your inputs':'Complete the highlighted fields to continue'}</p><div class="margin-pill">${ic(good&&r.belowCost?'info':'shield')}${good?num(r.effectiveMargin)+'% margin after adjustments':'Your costs come first'}</div></div><div class="summary-body">${good?`<div class="row"><span>Labor <small>(${num(r.crewHours)} person-hours)</small></span><strong>${money(r.labor)}</strong></div><div class="row"><span>Materials & supplies</span><strong>${money(draft.materials)}</strong></div><div class="row"><span>Travel & other costs</span><strong>${money(Number(draft.travel)+Number(draft.other))}</strong></div><div class="row"><span>Allocated overhead</span><strong>${money(r.overhead)}</strong></div><div class="row"><span>Contingency (${num(draft.contingency)}%)</span><strong>${money(r.buffer)}</strong></div><div class="row total"><span>Total job cost</span><strong>${money(r.cost)}</strong></div><div class="row profit"><span>Planned profit</span><strong>${money(r.profit)}</strong></div>${Number(draft.adjustment)!==0?`<div class="row"><span>${Number(draft.adjustment)>0?'Premium':'Discount'} (${num(draft.adjustment)}%)</span><strong>${money(r.adjustment)}</strong></div>`:''}${Number(draft.tax)>0?`<div class="row"><span>Tax (${num(draft.tax)}%)</span><strong>${money(r.taxAmount)}</strong></div><div class="row total"><span>Client total</span><strong>${money(r.total)}</strong></div>`:''}${r.belowCost?`<div class="notice danger">${ic('info')}This price loses ${money(-r.profit)} per job. Reduce the discount or update your costs before quoting.</div>`:r.belowTarget?`<div class="notice warning">${ic('info')}Your discount reduces the margin below your ${draft.margin}% target.</div>`:''}${r.minimumApplied?`<div class="notice">${ic('info')}Your minimum job charge sets the price.</div>`:''}`:`<div class="notice warning">${ic('info')}Check the values in the form. A valid labor rate and billable hours are required.</div>`}<button class="btn primary" data-action="${mode==='calc'?'to-quote':'to-preview'}" ${!good?'disabled':''}>${mode==='calc'?'Build client quote':'Preview client quote'} ${ic('arrow')}</button><p class="summary-note">${mode==='calc'?'No account. No guesswork. Your numbers, explained.':'Internal costs stay out of the client quote.'}</p><details class="explanation"><summary>How did we get this number? <span>＋</span></summary><p>${good?`Costs of ${money(r.cost)} ÷ (1 − ${draft.margin}% margin) = ${money(r.target)}. Then apply ${draft.adjustment}% adjustment, respect your ${money(draft.minimum)} minimum, and round up to the next ${money(draft.round)}.`:'Your price covers labor, direct costs, overhead and contingency, then adds your chosen profit margin.'}</p><a class="text-link" style="font-size:10px" href="#method">See every formula</a></details></div></div><div class="under-summary">${ic('lock')}Drafts stay in this browser. Export important quotes to keep a separate copy.</div>`}
function calcPage(){return heading('A fair price. A healthier business.','Know what the job costs. Charge what makes it worthwhile.',`<button class="btn secondary" data-action="reset">${ic('refresh')} Reset example</button>`)+steps(1)+`<div class="calculator-grid"><form id="calculator" novalidate><div class="eyebrow">MAKE THE NUMBERS WORK FOR YOU</div>${section('brief','The job at a glance','Start with a template, then make it yours.','01',`<div class="service-choices" role="group" aria-label="Service template">${Object.entries(PRESETS).map(([k,v])=>`<button type="button" class="chip ${draft.preset===k?'selected':''}" data-preset="${k}">${v.label}</button>`).join('')}</div><div class="fields">${field('job','Job or service name',{type:'text',full:true,maxlength:120,required:true})}</div><div class="notice">${ic('info')}Example numbers are a starting point, not local market rates. Replace them with your actual costs.</div>`)}${section('clock','Your time has value','Count the work, the people, and the time in between.','02',`<div class="fields">${field('hours','Working time per person',{min:.25,max:1000,suffix:'hrs',help:'Time on the job, for each team member.'})}${field('people','People on the job',{min:1,max:50,step:1,help:'Include yourself, even if you work alone.'})}${field('rate','Hourly labor cost per person',{min:.01,max:10000,prefix:true,help:'Your pay or loaded employee cost. Profit comes later.'})}${field('travelTime','Travel & admin per person',{max:100,suffix:'hrs',help:'Unpaid preparation, travel and follow-up time.'})}</div>`)}${section('coins','The costs behind the job','Small expenses add up. Give them a place.','03',`<div class="fields">${field('materials','Materials & supplies',{prefix:true})}${field('travel','Travel expenses',{prefix:true,help:'Fuel, mileage reimbursement, parking or tolls.'})}${field('other','Other direct job costs',{prefix:true,help:'Equipment rental, subcontractors or permits.'})}${field('monthly','Monthly business overhead',{prefix:true,help:'Insurance, software, equipment and fixed expenses.'})}${field('billable','Monthly billable person-hours',{min:1,max:10000,suffix:'hrs',help:'All sellable hours across your team, not calendar hours.'})}</div><div class="notice">${ic('info')}Overhead is spread across billable person-hours. Avoid including the same expense in two fields.</div>`)}${section('sliders','Make room for profit','Set your target and account for the unexpected.','04',`<div class="fields">${field('margin','Target profit margin',{max:90,suffix:'%',help:'Profit as a share of your selling price. This is not markup.'})}${field('contingency','Contingency buffer',{max:100,suffix:'%',help:'Covers uncertainty. Applied to all costs.'})}${field('adjustment','Pricing adjustment',{min:-50,max:100,suffix:'%',help:'Use −10 for a 10% discount or 15 for a 15% premium.'})}${field('minimum','Minimum job charge',{prefix:true,help:'Your minimum price before tax.'})}<div class="field"><label for="round">Round price up to</label><select id="round" data-price="round">${[1,5,10,25,50,100].map(n=>`<option value="${n}" ${Number(draft.round)===n?'selected':''}>Nearest ${money(n)}</option>`).join('')}</select><p class="help">Rounding up helps protect your margin.</p><div class="error" id="round-error"></div></div>${field('tax','Tax rate',{max:30,suffix:'%',help:'Default 0%. Enter only a rate you have verified.'})}${field('deposit','Deposit requested',{max:100,suffix:'%',help:'Share of the client total due before work starts.'})}</div>`)}<div class="form-bottom"><span>${ic('check')} Automatically saved in this browser</span><a href="#method" class="text-link">Understand the formulas</a></div></form><aside id="summary">${summary()}</aside></div>`}
function homePage(){return`<div class="hero"><div><div class="eyebrow">FOR THE BUSINESS YOU'RE BUILDING</div><h1>Good at your work.<br>Confident in your price.</h1><p>A simple way to turn your time and costs into a profitable price — and a quote you’ll feel good sending.</p><div class="inline-actions"><a class="btn primary" href="#calculator">Price your first job ${ic('arrow')}</a><a class="btn secondary" href="#method">Show me the math</a></div><p style="font-size:10px;margin:16px 0 0">No account needed · Transparent formulas · Ready in minutes</p></div><div class="mini-quote"><div class="label">ILLUSTRATIVE CLEANING JOB</div><h2>Standard home cleaning <span style="float:right;color:#91a17d">↗</span></h2><div class="row"><span>Time, supplies & travel</span><strong>$115.50</strong></div><div class="row"><span>Overhead & contingency</span><strong>$19.56</strong></div><div class="row"><span>Planned profit</span><strong>$59.94</strong></div><div class="row total"><span>Your price, before tax</span></div><div class="mini-total">$195.00</div><div class="status" style="display:inline-block">30.7% planned margin</div><div class="bar"><span></span><span></span><span></span></div></div></div><div class="grid3">${[['clock','Start with the whole job','Count the work you do before, during and after the appointment. Your time belongs in the price.'],['shield','See the profit you keep','Set a real margin, include overhead, and understand what a discount does to your earnings.'],['quotes','Make it client-ready','Turn the recommendation into a branded quote with scope, terms, tax and a deposit.']].map(([i,h,p])=>`<section class="card feature"><div class="icon-box">${ic(i)}</div><h3>${h}</h3><p>${p}</p></section>`).join('')}</div><div class="section-title"><h2>A small tool with a complete workflow.</h2><a class="text-link" href="#launch" style="font-size:11px">Your first-customer plan ${ic('arrow')}</a></div><div class="card form-card"><div class="grid3">${[['01','Tell us about the job','Use the cleaning, lawn care, creative or custom template. Every number is editable.'],['02','Understand your recommendation','See exactly what covers costs and what remains as planned profit.'],['03','Send a quote with confidence','Add your client, spell out the scope, then copy or print a clean PDF.']].map(([n,h,p])=>`<div><div class="eyebrow">${n}</div><h3>${h}</h3><p class="subtitle" style="font-size:12px">${p}</p></div>`).join('')}</div></div><div class="notice">${ic('lock')}You’re reviewing a private MVP. Quotes and setup briefs are stored in this browser. Sending, payments and scheduling are handled outside the app.</div>`}
function quotePage(){const pf=(k,l,o={})=>field(k,l,{...o,value:profile[k]??'',data:`data-profile="${k}"`,ns:'profile-',type:o.type||'text',maxlength:200});const df=(k,l,o={})=>field(k,l,{...o,value:details[k]??'',data:`data-details="${k}"`,ns:'details-',type:o.type||'text',maxlength:200});return heading('Turn your price into a clear yes.','Add the details your client needs. Keep your cost breakdown private.',`<a class="btn secondary" href="#calculator">${ic('edit')} Edit pricing</a>`)+steps(2)+`<div class="calculator-grid"><form id="quote-form" novalidate>${section('brief','Your business','A professional quote starts with your name.','01',`<div class="fields">${pf('name','Business name',{full:true,required:true})}${pf('email','Business email <span class="optional">(optional)</span>',{type:'email'})}${pf('phone','Phone <span class="optional">(optional)</span>')}</div>`)}${section('quotes','Your client & the scope','Be specific about what the price includes.','02',`<div class="fields">${df('client','Client name or business',{full:true,required:true})}${df('email','Client email <span class="optional">(optional)</span>',{type:'email'})}${df('address','Service location <span class="optional">(optional)</span>')}<div class="field full"><label for="scope">Scope of work</label><textarea id="scope" data-details="scope" maxlength="4000" required aria-describedby="scope-error">${esc(details.scope)}</textarea><p class="help">Include deliverables, quantity, exclusions and revision limits.</p><div class="error" id="scope-error"></div></div></div>`)}${section('book','Terms & timing','Set expectations before the work begins.','03',`<div class="fields">${df('validDays','Quote valid for',{type:'number',min:1,max:90,suffix:'days'})}<div class="field"><label>Deposit</label><div style="font-size:19px;font-weight:650;padding-top:4px">${money(calculate(draft).depositAmount)}</div><p class="help">${draft.deposit}% of the total. <a href="#calculator" class="text-link">Change in calculator</a></p></div><div class="field full"><label for="terms">Payment & approval terms</label><textarea id="terms" data-profile="terms" maxlength="3000">${esc(profile.terms)}</textarea></div><div class="field full"><label for="notes">Client note <span class="optional">(optional)</span></label><textarea id="notes" data-details="notes" maxlength="2000" placeholder="Thank you for the opportunity. We look forward to working with you.">${esc(details.notes)}</textarea></div></div>`)}<p class="help">Your quote is a draft offer until agreed with the client. Confirm the scope and any applicable tax before sending.</p></form><aside id="summary">${summary('quote')}</aside></div>`}
function snapshot(){const today=new Date(),valid=new Date();valid.setDate(valid.getDate()+Number(details.validDays));return{id:'PMS-'+today.toISOString().slice(0,10).replaceAll('-','')+'-'+Math.random().toString(36).slice(2,6).toUpperCase(),created:today.toISOString(),valid:valid.toISOString(),currency:currency(),profile:{...profile},details:{...details},draft:{...draft},result:calculate(draft),status:'Draft'}}
function quotePaper(q){const r=q.result,m=n=>money(n,q.currency);return`<article class="quote-paper" aria-label="Client quote"><div class="quote-letterhead"><div><h2>${esc(q.profile.name)}</h2><p>${esc([q.profile.email,q.profile.phone,q.profile.address].filter(Boolean).join('\n'))}</p></div><div style="text-align:right"><div class="quote-stamp">QUOTE</div><p>${esc(q.id)}</p></div></div><div class="quote-meta"><div><div class="label">PREPARED FOR</div><p><strong>${esc(q.details.client)}</strong><br>${esc(q.details.email)}${q.details.address?'<br>'+esc(q.details.address):''}</p></div><div style="text-align:right"><p><span class="label">ISSUED</span><br>${date(q.created)}</p><p><span class="label">VALID UNTIL</span><br>${date(q.valid)}</p></div></div><table class="quote-table"><thead><tr><th>Service</th><th>Amount (${esc(q.currency)})</th></tr></thead><tbody><tr><td>${esc(q.draft.job)}</td><td>${m(r.price)}</td></tr></tbody></table><div class="quote-totals"><div class="row"><span>Subtotal</span><strong>${m(r.price)}</strong></div><div class="row"><span>Tax (${num(q.draft.tax)}%)</span><strong>${m(r.taxAmount)}</strong></div><div class="row total"><span>Quote total</span><strong>${m(r.total)}</strong></div><div class="row"><span>Deposit (${num(q.draft.deposit)}%)</span><strong>${m(r.depositAmount)}</strong></div><div class="row"><span>Balance after deposit</span><strong>${m(r.balance)}</strong></div></div><div class="quote-scope"><div class="label">SCOPE OF WORK</div>${esc(q.details.scope)}</div>${q.details.notes?`<div class="quote-scope"><div class="label">A NOTE FOR YOU</div>${esc(q.details.notes)}</div>`:''}<div class="quote-terms"><div class="label">TERMS & APPROVAL</div>${esc(q.profile.terms)}${Number(q.draft.deposit)>0?'\nDeposit due after approval and before work begins.':''}</div><div class="quote-approval">Client approval: ______________________________ &nbsp; Date: ______________</div></article>`}
function previewPage(saved=false,ready=false){if(!currentQuote)currentQuote=snapshot();const q=currentQuote;return heading(ready?'Your quote is ready.':saved?'A quote worth keeping.':'Here’s what your client will see.',ready?'Saved in this browser. Export a copy, then share it directly with your client.':'Review the scope, numbers and terms before you share.',`<a class="btn secondary" href="${saved?'#quotes':'#quote'}">${ic('edit')} ${saved?'All quotes':'Edit details'}</a>`)+(!saved?steps(ready?3:2):'')+(ready?`<div class="success-banner">${ic('check')}<div><h2>One step closer to your next customer.</h2><p>Download or copy the quote, send it yourself, and follow up in two business days.</p></div></div>`:'')+`<div class="quote-layout">${quotePaper(q)}<aside><section class="card form-card"><div class="eyebrow">CLIENT-READY</div><h2 style="margin-bottom:18px">${money(q.result.total,q.currency)} <span style="font-size:11px;color:var(--muted);font-weight:400">total</span></h2><div class="action-stack">${!saved&&!ready?`<button class="btn primary" data-action="save-quote">${ic('check')} Save quote & finish</button>`:''}<button class="btn ${saved||ready?'primary':'secondary'}" data-action="print">${ic('print')} Print / Save as PDF</button><button class="btn secondary" data-action="copy-quote">${ic('copy')} Copy client quote</button><button class="btn secondary" data-action="download-quote">${ic('download')} Download quote (.txt)</button></div><div class="notice">${ic('shield')}Only the service price, scope and terms appear in your client quote. Labor cost, margin and profit stay private.</div><p class="help" style="margin-top:18px">Nothing is sent automatically. Use your usual email or messaging app to share the exported quote.</p></section>${saved||ready?`<section class="card form-card"><h3>Keep the conversation moving</h3><p class="subtitle" style="font-size:11px;margin:12px 0 18px">Send the quote → Confirm scope → Get written approval → Collect the deposit.</p><label class="field"><span style="font-size:11px;font-weight:600">Quote status</span><select id="quote-status" style="margin-top:7px" data-quote-status="${esc(q.id)}">${['Draft','Sent','Accepted','Declined'].map(s=>`<option ${q.status===s?'selected':''}>${s}</option>`).join('')}</select></label><button class="btn ghost small" style="margin-top:12px" data-action="follow-up">${ic('copy')} Copy a follow-up message</button></section><a class="btn secondary" href="#calculator" style="width:100%">${ic('plus')} Price another job</a>`:''}</aside></div>`}
function quoteText(q){const r=q.result,m=n=>money(n,q.currency);return`${q.profile.name}\n${[q.profile.email,q.profile.phone].filter(Boolean).join(' · ')}\n\nQUOTE ${q.id}\nIssued: ${date(q.created)}\nValid until: ${date(q.valid)}\nPrepared for: ${q.details.client}${q.details.email?'\n'+q.details.email:''}${q.details.address?'\nLocation: '+q.details.address:''}\n\n${q.draft.job}: ${m(r.price)}\nTax (${q.draft.tax}%): ${m(r.taxAmount)}\nTOTAL (${q.currency}): ${m(r.total)}\nDeposit (${q.draft.deposit}%): ${m(r.depositAmount)}\nBalance after deposit: ${m(r.balance)}\n\nSCOPE OF WORK\n${q.details.scope}\n\nTERMS\n${q.profile.terms}${Number(q.draft.deposit)>0?'\nDeposit due after approval and before work begins.':''}${q.details.notes?'\n\nNOTE\n'+q.details.notes:''}\n\nPlease reply to confirm the scope and approve this quote before work begins. Thank you.`}
function quotesPage(){return heading('Your quotes, all in one place.','Keep track of the jobs you’re building your business on.',`<a class="btn primary" href="#calculator">${ic('plus')} New quote</a>`)+(quotes.length?`<div class="card table-scroll"><table class="quote-list"><thead><tr><th>Client / service</th><th>Created</th><th>Total</th><th>Status</th><th>Actions</th></tr></thead><tbody>${quotes.map(q=>`<tr><td><strong>${esc(q.details.client)}</strong><small>${esc(q.draft.job)}</small></td><td>${date(q.created)}</td><td>${money(q.result.total,q.currency)}</td><td><span class="status">${esc(q.status)}</span></td><td><div class="inline-actions"><a class="btn secondary small" href="#view/${esc(q.id)}">Open ${ic('arrow')}</a><button class="btn ghost small" data-delete="${esc(q.id)}" aria-label="Delete quote for ${esc(q.details.client)}">${ic('trash')}</button></div></td></tr>`).join('')}</tbody></table></div><div class="notice">${ic('lock')}Quotes are stored on this browser and device. Export a backup before clearing browser data.<button class="btn ghost small" data-action="export-all">Export backup ${ic('download')}</button></div>`:`<div class="card empty">${ic('quotes')}<h2>Your next job starts here.</h2><p>Price a job, add your client’s details, and save your first quote. It will appear right here.</p><a href="#calculator" class="btn primary">Create your first quote ${ic('arrow')}</a></div>`)}
function methodPage(){return heading('Clear math. No black box.','You choose the inputs. Every recommendation follows the same visible rules.')+`<div class="reading"><section class="card form-card"><div class="eyebrow">THE PRICEMYService METHOD</div>${[['Time & labor','Person-hours = (working hours + travel/admin hours) × people. Labor cost = person-hours × hourly labor cost.','Pay yourself for your time. Employee rates should include the employment costs you actually incur.'],['Overhead & direct costs','Overhead per hour = monthly overhead ÷ monthly billable person-hours. Job overhead = hourly overhead × job person-hours.','Add materials, travel expenses and other direct costs once. Keep fixed business expenses in monthly overhead.'],['Contingency & target margin','Total cost = (labor + direct expenses + overhead) × (1 + contingency %). Target price = total cost ÷ (1 − margin %).','A 30% margin on a $100 cost means $142.86 before rounding. Adding a 30% markup would produce $130 and only a 23.08% margin.'],['Adjustments & the minimum','Adjusted price = target price × (1 + adjustment %). Recommendation = round UP max(adjusted price, minimum charge).','Use a negative adjustment for a discount. Discounts lower your actual margin; the calculator flags this. Rounding is always upward.'],['Tax & the deposit','Tax = price × tax rate. Client total = price + tax. Deposit = client total × deposit %. Balance = total − deposit.','Tax and deposit are rounded to cents. Tax is passed through and excluded from profit. A deposit changes payment timing, not the price.']].map(([h,f,p],i)=>`<div class="method-row"><div class="number">0${i+1}</div><div><h3>${h}</h3><div class="formula">${f}</div><p>${p}</p></div></div>`).join('')}<div class="notice warning">${ic('info')}This is a cost-based recommendation, not a demand forecast or market-rate lookup. Review your scope, local market, business costs and any applicable tax before offering the quote. Planned profit includes a contingency reserve until the actual costs are known.</div></section><div class="section-title"><h2>From a number to a conversation.</h2></div><div class="card table-scroll"><table class="comparison"><thead><tr><th>Step</th><th>A standalone calculation</th><th>PriceMyService workflow</th></tr></thead><tbody><tr><td>Your time</td><td>Hourly rate × hours</td><td>Work, travel, admin and team size</td></tr><tr><td>Healthy pricing</td><td>One output number</td><td>Visible cost breakdown and margin warnings</td></tr><tr><td>Client handoff</td><td>Copy the price manually</td><td>Scope, terms, deposit and clean quote</td></tr><tr><td>First sale</td><td>No next step</td><td>Pilot brief and a 7-day launch checklist</td></tr></tbody></table></div><p class="help" style="margin:10px 0 25px">Comparison describes workflows, rather than claims about any specific competing product.</p><a class="btn primary" href="#calculator">Put the method to work ${ic('arrow')}</a></div>`}
const launchTasks=[['Pick one customer','Start with an independent house cleaner. Offer a calculator configured to their own rate card.'],['Build one believable demo','Use their real labor, supply and overhead costs. Prepare one example quote together.'],['Find 10 suitable businesses','Use your own network or local business listings. Focus on owners who still quote manually.'],['Start five conversations','Ask how they price and where quoting breaks down. Show the demo after you understand the problem.'],['Offer one $99 pilot','One configured calculator, branded quote template and walkthrough. Use an external invoice after written scope approval.'],['Deliver and test together','Check three real jobs with the owner. Get rate-card approval and show how to export quotes.'],['Ask for feedback and one introduction','Document the time saved or a pricing mistake found. Get permission before using any testimonial.']];
function launchPage(){return heading('One customer. One useful result.','A small, practical path from private MVP to your first paid pilot.')+`<section class="launch-head"><div><div class="eyebrow" style="color:var(--lime)">YOUR FOUNDING-CUSTOMER OFFER</div><h2>A pricing setup for one service business.</h2><p>Configure the calculator to the owner’s costs, add their brand and quote terms, then hand it over with a simple walkthrough. Offer a two-business-day setup after receiving complete information.</p></div><div class="launch-price"><div class="amount">$99</div><small>Suggested one-time pilot price<br>No mandatory subscription</small></div></section><div class="launch-grid"><section class="card"><div style="padding:23px 23px 18px"><div class="section-head" style="margin-bottom:18px"><div><h2>Your 7-day launch checklist</h2><p id="task-count">${tasks.length} of 7 completed</p></div>${ic('rocket')}</div><div class="progress-track"><div id="task-progress" style="width:${tasks.length/7*100}%"></div></div></div><div class="checklist">${launchTasks.map(([h,p],i)=>`<div class="task"><input id="task-${i}" type="checkbox" data-task="${i}" ${tasks.includes(i)?'checked':''}><label for="task-${i}"><strong>${h}</strong><p>${p}</p></label><span class="day">Day ${i+1}</span></div>`).join('')}</div></section><div><section class="card form-card"><div class="eyebrow">FIRST-CUSTOMER FLOW</div><h2>Prepare a pilot setup brief</h2><p class="subtitle" style="font-size:11px;margin:8px 0 22px">Use this with a business owner after they’ve tried the calculator. Export it to agree the work before invoicing.</p><form id="pilot-form" novalidate><div class="fields">${field('business','Business name',{value:pilot.business,type:'text',data:'data-pilot="business"',ns:'pilot-',full:true,maxlength:200,required:true})}${field('email','Owner’s email',{value:pilot.email,type:'email',data:'data-pilot="email"',ns:'pilot-',full:true,maxlength:200,required:true})}${field('service','Primary service',{value:pilot.service,type:'text',data:'data-pilot="service"',ns:'pilot-',full:true,maxlength:200,required:true})}<div class="field full"><label for="pilot-goal">What do they need help pricing?</label><textarea id="pilot-goal" data-pilot="goal" maxlength="2000" placeholder="For example: standard and deep cleans, travel time, supply costs and minimum call-out charge.">${esc(pilot.goal)}</textarea></div></div><button type="submit" class="btn primary" style="width:100%;margin-top:20px">Prepare setup brief ${ic('arrow')}</button><p class="help" style="margin-top:11px">Saved on this device. This form does not send an inquiry or take payment.</p></form></section><section class="card form-card"><h3>A conversation starter</h3><p class="subtitle" style="font-size:12px;margin:12px 0 15px">“How do you check that a job covers your supplies, travel and time? I’ve built a simple pricing tool and would love your feedback on one real quote.”</p><button class="btn secondary small" data-action="copy-outreach">${ic('copy')} Copy message</button></section></div></div>`}
function pilotText(){return`PRICEMYSERVICE — PILOT SETUP BRIEF\n\nBusiness: ${pilot.business}\nOwner email: ${pilot.email}\nService: ${pilot.service}\nPricing challenge: ${pilot.goal||'Discuss during setup'}\n\nPROPOSED PILOT: $99 one-time\nIncludes one calculator configured to the business’s actual costs and approved rate card; branded client quote with scope, tax and deposit settings; walkthrough and checks against three real jobs.\nTarget handover: two business days after complete inputs and scope approval.\nNo mandatory subscription.\n\nOWNER TO PROVIDE\nBusiness name/contact, services and exclusions, labor/time estimates, direct costs, monthly overhead, billable capacity, target margin, verified tax rate and payment terms.\n\nBEFORE PAYMENT\nConfirm deliverables, access and handover method, support period and refund terms in writing. Then issue an external invoice. This brief is not an invoice and no payment has been collected.\n\nPrivate MVP: data is browser-local; no email delivery, client portal, scheduling or payment processing is included.`}
function pilotReady(){return heading('Your pilot brief is prepared.','A concrete next step for your first customer.')+`<div class="success-banner">${ic('check')}<div><h2>Ready to review with ${esc(pilot.business)}.</h2><p>This has been saved on this device. Nothing has been sent and no payment has been collected.</p></div></div><section class="card form-card reading"><h2>Review the proposed scope together</h2><pre style="font:inherit;font-size:12px;white-space:pre-wrap;line-height:1.8;color:var(--muted);margin:20px 0">${esc(pilotText())}</pre><div class="inline-actions"><button class="btn primary" data-action="download-pilot">${ic('download')} Download setup brief</button><button class="btn secondary" data-action="copy-pilot">${ic('copy')} Copy brief</button><a href="#launch" class="btn ghost">Edit brief</a></div></section>`}
function settingsPage(){return heading('Make it your business.','Your business details appear on new quotes. Saved quotes keep their original details.')+`<section class="card form-card reading"><form id="profile-form"><div class="fields">${['name','email','phone','address'].map((k,i)=>field(k,['Business name','Business email','Phone','Business address'][i],{value:profile[k],type:k==='email'?'email':'text',data:`data-profile="${k}"`,ns:'settings-',full:i===0||i===3,maxlength:200})).join('')}<div class="field"><label for="currency">Quote currency</label><select id="currency" data-profile="currency">${[['USD','US dollar (USD)'],['CAD','Canadian dollar (CAD)'],['GBP','British pound (GBP)'],['EUR','Euro (EUR)'],['AUD','Australian dollar (AUD)'],['INR','Indian rupee (INR)']].map(([v,l])=>`<option value="${v}" ${currency()===v?'selected':''}>${l}</option>`).join('')}</select><p class="help">Changes the currency label only. Enter costs in that currency; no exchange conversion.</p></div><div class="field full"><label for="settings-terms">Default quote terms</label><textarea id="settings-terms" data-profile="terms" maxlength="3000">${esc(profile.terms)}</textarea></div></div><div class="inline-actions" style="margin-top:24px"><button class="btn primary" type="submit">${ic('check')} Save business details</button><a class="btn secondary" href="#calculator">Go to calculator ${ic('arrow')}</a></div></form></section><div class="notice reading">${ic('lock')}Details save automatically on this browser. No account or cloud synchronization is required.</div>`}
function privacyPage(){return heading('Your numbers belong to you.','A straightforward approach to data in this MVP.')+`<section class="card form-card reading legal"><h2 style="margin-bottom:20px">What is stored</h2><p>PriceMyService stores calculator drafts, business details, client quote details, quotes and your launch checklist in this browser’s local storage. They are not synchronized between devices or sent to an application database. Other people using this browser profile may be able to see them.</p><h3>What leaves this page</h3><p>Using copy, download or print exports the content you choose to your clipboard, a local file or your browser’s print workflow. No quotes or inquiries are emailed automatically. This MVP has no advertising trackers, third-party analytics, AI calls, checkout or client portal. Hosting infrastructure still handles normal web requests. Website access depends on your hosting settings.</p><h3>Keep a separate copy</h3><p>Browser data can be cleared or unavailable in private browsing. Export important quotes and a backup. Do not use the browser as your only business record.</p><h3>Calculation limits</h3><p>Defaults are illustrative. Prices reflect your supplied costs and chosen margin, not competitor rates or a promise of sales. Confirm the scope, costs, any applicable tax and agreement with your client before work starts.</p><div class="inline-actions" style="margin-top:24px"><button class="btn secondary" data-action="export-all">${ic('download')} Export quote backup</button><button class="btn secondary danger-text" data-action="clear-data">${ic('trash')} Clear all local app data</button></div></section>`}
function render(){let path=(location.hash.slice(1)||'calculator'),base=path.split('/')[0],active=['quote','preview','ready'].includes(base)?'calculator':base==='view'?'quotes':base;const pageNames={home:'Overview',calculator:'Pricing calculator',quote:'Build your quote',preview:'Quote preview',ready:'Quote ready',view:'Saved quote',quotes:'My quotes',method:'How it works',launch:'First customer',settings:'Business profile',privacy:'Privacy & data','pilot-ready':'Pilot brief'};let page;if(base==='view'){const q=quotes.find(q=>q.id===path.split('/')[1]);if(q){currentQuote=q;page=previewPage(true)}else page=heading('That quote isn’t here.','It may have been deleted or saved in another browser.',`<a href="#quotes" class="btn primary">Go to my quotes</a>`)}else page=({home:homePage,calculator:calcPage,quote:quotePage,preview:()=>previewPage(),ready:()=>previewPage(false,true),quotes:quotesPage,method:methodPage,launch:launchPage,settings:settingsPage,privacy:privacyPage,'pilot-ready':pilotReady}[base]||calcPage)();$('#app').innerHTML=`<div class="shell"><aside class="sidebar">${brand()}<div class="workspace-label">YOUR WORKSPACE</div><nav class="nav" aria-label="Main navigation">${[['home','home','Overview'],['calculator','calc','Pricing calculator'],['quotes','quotes','My quotes'],['method','book','How it works'],['launch','rocket','First customer']].map(([p,i,l])=>`<a href="#${p}" class="${active===p?'active':''}" ${active===p?'aria-current="page"':''}>${ic(i)}${l}</a>`).join('')}</nav><div class="side-bottom"><div class="tip">${ic('leaf')}<strong>Build a business that lasts.</strong><p>A good price covers today’s work and makes room for tomorrow.</p></div><a class="profile-link" href="#settings"><div class="avatar">${esc(profile.name?profile.name.slice(0,2).toUpperCase():'YB')}</div><span><strong>${esc(profile.name||'Your business')}</strong><small>Business profile ${ic('chevron')}</small></span></a></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">Workspace <span style="color:#b1b9ac;margin:0 7px">/</span><span>${pageNames[base]||'Pricing calculator'}</span></div><div class="mobile-brand">${brand()}</div><div class="top-actions"><div class="private-badge">${ic('lock')} Browser workspace</div><button class="mobile-menu" aria-label="Open navigation" aria-expanded="false">${ic('menu')}</button></div></header>${storageOK?'':'<div class="storage-warning">Browser storage is unavailable. Export your work before leaving this page.</div>'}<div class="content">${page}${foot()}</div></main></div>`;if(base==='calculator')showPriceErrors();document.title=(pageNames[base]||'Calculator')+' — PriceMyService'}
function showPriceErrors(){const errors=validate(draft);for(const input of document.querySelectorAll('[data-price]')){const k=input.dataset.price,e=$('#'+k+'-error');input.setAttribute('aria-invalid',!!errors[k]);if(e)e.textContent=errors[k]||''}return errors}
function validateQuote(){let valid=true;const checks=[['profile-name',profile.name.trim()?'':'Enter your business name.'],['details-client',details.client.trim()?'':'Enter a client name.'],['scope',details.scope.trim().length>=10?'':'Describe the scope in at least 10 characters.'],['details-validDays',Number.isInteger(Number(details.validDays))&&Number(details.validDays)>=1&&Number(details.validDays)<=90?'':'Choose 1 to 90 whole days.']];for(const [id,value]of[['profile-email',profile.email],['details-email',details.email]])checks.push([id,!value||/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)?'':'Enter a valid email or leave this blank.']);let first;for(const[id,msg]of checks){const el=$('#'+id),error=$('#'+id+'-error');if(el)el.setAttribute('aria-invalid',!!msg);if(error)error.textContent=msg;if(msg){valid=false;first??=el}}if(first)first.focus();return valid}
function ask(title,message,action){const div=document.createElement('div');div.className='dialog-backdrop';div.innerHTML=`<section class="dialog" role="alertdialog" aria-modal="true" aria-labelledby="dialog-title"><h2 id="dialog-title">${title}</h2><p>${message}</p><div class="inline-actions"><button class="btn secondary" id="cancel-dialog">Cancel</button><button class="btn primary" id="confirm-dialog">Confirm</button></div></section>`;document.body.append(div);$('#cancel-dialog').focus();$('#cancel-dialog').onclick=()=>div.remove();$('#confirm-dialog').onclick=()=>{div.remove();action()};div.onkeydown=e=>{if(e.key==='Escape')div.remove();if(e.key==='Tab'){e.preventDefault();(document.activeElement===$('#cancel-dialog')?$('#confirm-dialog'):$('#cancel-dialog')).focus()}}}
document.addEventListener('input',e=>{const el=e.target;if(el.dataset.price){const k=el.dataset.price;draft[k]=el.value;put('draft',draft);showPriceErrors();$('#summary').innerHTML=summary()}if(el.dataset.profile){profile[el.dataset.profile]=el.value;put('profile',profile)}if(el.dataset.details){details[el.dataset.details]=el.value;put('details',details)}if(el.dataset.pilot){pilot[el.dataset.pilot]=el.value;put('pilot',pilot)}});
document.addEventListener('change',e=>{if(e.target.dataset.task){const n=Number(e.target.dataset.task);tasks=e.target.checked?[...new Set([...tasks,n])]:tasks.filter(x=>x!==n);put('tasks',tasks);$('#task-count').textContent=tasks.length+' of 7 completed';$('#task-progress').style.width=tasks.length/7*100+'%'}if(e.target.dataset.quoteStatus){const q=quotes.find(q=>q.id===e.target.dataset.quoteStatus);if(q){q.status=e.target.value;put('quotes',quotes);toast('Quote status updated.')}}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='calculator'&&!Object.keys(validate(draft)).length){currentQuote=null;go('quote');}if(e.target.id==='profile-form'){put('profile',profile);toast('Business details saved.');render()}if(e.target.id==='pilot-form'){let bad=false;for(const k of['business','email','service']){const el=$('#pilot-'+k),msg=!pilot[k].trim()?'This field is required.':k==='email'&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(pilot.email)?'Enter a valid email.':'';$('#pilot-'+k+'-error').textContent=msg;el.setAttribute('aria-invalid',!!msg);if(msg&&!bad){el.focus();bad=true}}if(!bad){put('pilot',pilot);go('pilot-ready')}}});
document.addEventListener('click',async e=>{const menu=e.target.closest('.mobile-menu');if(menu){const open=$('.sidebar').classList.toggle('open');menu.setAttribute('aria-expanded',open);return}if($('.sidebar.open')&&!e.target.closest('.sidebar'))$('.sidebar').classList.remove('open');const preset=e.target.closest('[data-preset]');if(preset){const apply=()=>{draft={...PRESETS[preset.dataset.preset],preset:preset.dataset.preset};details.scope=draft.scope;put('draft',draft);put('details',details);currentQuote=null;render();toast('Example template loaded. Adjust it to your actual costs.')};ask('Load this service template?','This replaces the current job inputs and scope with editable example numbers. Saved quotes stay available.',apply);return}const del=e.target.closest('[data-delete]');if(del){ask('Delete this quote?','This removes the quote from this browser. Export a copy first if you need to keep it.',()=>{quotes=quotes.filter(q=>q.id!==del.dataset.delete);put('quotes',quotes);render();toast('Quote deleted.')});return}const a=e.target.closest('[data-action]')?.dataset.action;if(!a)return;if(a==='reset'){ask('Reset this example?','This replaces your current job inputs and scope with the selected template. Saved quotes stay available.',()=>{draft={...PRESETS[draft.preset||'cleaning'],preset:draft.preset||'cleaning'};details.scope=draft.scope;put('draft',draft);put('details',details);render()})}if(a==='to-quote'){if(!Object.keys(showPriceErrors()).length){currentQuote=null;go('quote')}}if(a==='to-preview'){if(validateQuote()){currentQuote=snapshot();put('activeQuote',currentQuote);go('preview')}}if(a==='save-quote'){if(!currentQuote)return;quotes=[currentQuote,...quotes.filter(q=>q.id!==currentQuote.id)];if(put('quotes',quotes))go('ready')}if(a==='print')window.print();if(a==='copy-quote'&&currentQuote)await copy(quoteText(currentQuote));if(a==='download-quote'&&currentQuote)download(currentQuote.id+'.txt',quoteText(currentQuote));if(a==='export-all')download('pricemyservice-quotes-backup.json',JSON.stringify({app:'PriceMyService',exported:new Date().toISOString(),quotes},null,2),'application/json');if(a==='follow-up'&&currentQuote)await copy(`Hi ${currentQuote.details.client}, just checking whether you had a chance to review quote ${currentQuote.id} for ${currentQuote.draft.job}. I’m happy to clarify the scope or answer any questions. If you’d like to go ahead, please reply with your approval. Thank you!`);if(a==='copy-outreach')await copy('Hi! How do you check that a job covers your supplies, travel and time? I’ve built a simple pricing tool and would love your feedback on one real quote. Would you be open to a short walkthrough?');if(a==='download-pilot')download('PriceMyService-pilot-setup-brief.txt',pilotText());if(a==='copy-pilot')await copy(pilotText());if(a==='clear-data')ask('Clear all local app data?','This deletes drafts, business details, saved quotes, pilot details and checklist progress from this browser. Export anything you need first.',()=>{try{for(const k of['draft','profile','details','quotes','tasks','pilot','activeQuote'])localStorage.removeItem('pms-'+k)}catch{}location.href=location.pathname+'#calculator';location.reload()})});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
